  StageGroup_120951_Desc = {
    Text = "ปลายอีกด้านของมิติ เสียงเรียกอันแผ่วเบาจากบ้านเกิดที่ห่างหายไปนาน \n ความตระหนักของเทพเจ้าได้ทอดมองไปยังการทำลายอีกครั้ง ขวางมัน เอาชนะมัน ข้ามผ่านกาลเวลาและอวกาศที่ห่างไกล กลับมายืนอยู่ต่อหน้ากันอีกครั้ง \n สัญญา ในเส้นทางยาวและมืดมิดนี้ มันจะเป็นเพียงจุดแสงเดียวที่ชี้นำเรา."
