  StageGroup_125684_Desc = {
    Text = "เอี๊ยด——เอี๊ยด——เทพีแห่งโชคชะตาหมุนกี่ทอของนาง\nเอี๊ยด——เอี๊ยด——สายด้ายแห่งชะตากรรมมารวมกันในมือของนาง\nหุ่นเชิดเข้าแถวขึ้นเวที ก้าวเข้าสู่ข่ายใยแห่งโชคชะตา\nพวกมันเต้นรำ พวกมันร้องเพลง เอี๊ยด——เอี๊ยด——\nพวกมันตายไปพร้อมกับข่ายใยนั้น อย่างเงียบงัน"
