    Text = "ความโลภมักมอบสิ่งที่มากขึ้นให้ แต่ผู้ที่พอใจกับสิ่งน้อยจะสูญเสียทุกอย่างที่ตนมีไป\nเมื่อเรามองไปที่มหาสมุทร สิ่งที่เรามองไม่ใช่เพียงแค่ความกว้างใหญ่และความงามของมัน มหาสมุทรกลืนกินความทรงจำ มหาสมุทรกลืนกินความกลัว ทุกการรวมตัวของกระแสน้ำหายไปในพริบตา\nมหาสมุทรกำลังเรียกเธอ ให้จมลงสู่ความเงียบสงบอันเป็นนิรันดร์."
