  StageGroup_145355_Name = {
    Text = "กระจกไร้เงา"
  },
  StageGroup_145355_TypeText = {
    Text = "การประลองแห่งการสังหาร"
  },
  StageGroup_145356_Desc = {
    Text = "หนึ่งหมื่นสองพันปีแห่งการเฝ้ารอ เลวีอาธานเบื่อหน่ายมานานแล้ว.\nบรรดากษัตริย์สวมมงกุฎใต้พระบาทของพระองค์ นักบุญกลายเป็นผู้เต็มไปด้วยความโลภต่อหน้าพระองค์ วีรบุรุษอาบกายในความโลภอำนาจอันหาที่สิ้นสุดมิได้ของพระองค์อย่างสงบ. มงกุฎที่เปื้อนเลือดหล่นลง จากกะโหลกหนึ่งสู่อีกกะโหลกหนึ่ง.\nพระองค์เคี้ยวฉากซ้ำซากเหล่านั้น ดั่งการกลืนกินฝุ่นจืดชืดในกาแล็กซี. พระองค์เคยคิดว่านี่คือทั้งหมดที่จะได้เห็นในชีวิตอันเป็นนิรันดร์ของพระองค์.\nจนกระทั่งเธอมาปรากฏต่อหน้าพระองค์."
  },
  StageGroup_145356_Name = {
    Text = "จนกว่าวาฬแห่งฟากฟ้าจะร่วงหล่น"
  },
  StageGroup_145356_TypeText = {
    Text = "การล่องเรือในจิตสำนึก"
  },
  StageGroup_145357_Name = {
    Text = "สัตว์ร้ายในกรง"
  },
  StageGroup_145357_TypeText = {
    Text = "การประลองแห่งการสังหาร"
  },
  StageGroup_145358_Name = {
    Text = "วิหารแห่งการสังหาร"
  },
  StageGroup_145358_TypeText = {
    Text = "การประลองแห่งการสังหาร"
  },
  StageGroup_145359_Name = {
    Text = "มงกุฎแห่งความโลภอำนาจ"
  },
  StageGroup_145359_TypeText = {
    Text = "การประลองแห่งการสังหาร"
  },
  StageGroup_145360_Name = {
    Text = "การเข้าเฝ้าถวาย"
  },
  StageGroup_145360_TypeText = {
    Text = "การประลองแห่งการสังหาร"
  },
  StageGroup_146256_Desc = {
    Text = "ขุนเขาตั้งตระหง่านอยู่ ณ ปลายสุดของโลก.\nเหนือผืนหิมะและหยาดน้ำฟ้าที่แข็งตัวตลอดกาล ความหิวโหยอันเก่าแก่กำลังตื่นขึ้นจากการหลับใหลอันยาวนาน.\nภูเขาอ้าปากกว้าง แล้วปล่อยเสียงหัวเราะต่ำทุ้มเยาะเย้ย.\nเฝ้ารอด้วยความอดทนเถิด—— ผู้มีความปรารถนากำลังอยู่บนทางไปสู่งานเลี้ยง."
  },
  StageGroup_146256_Name = {
    Text = "ยามขุนเขาเริงสำราญ"
  },
  StageGroup_146256_TypeText = {
    Text = "การสืบสวนยาก"
  },
  StageGroup_146257_Desc = {
    Text = "ขุนเขาตั้งตระหง่านอยู่ ณ ปลายสุดของโลก.\nเหนือผืนหิมะและหยาดน้ำฟ้าที่แข็งตัวตลอดกาล ความหิวโหยอันเก่าแก่กำลังตื่นขึ้นจากการหลับใหลอันยาวนาน.\nภูเขาอ้าปากกว้าง แล้วปล่อยเสียงหัวเราะต่ำทุ้มเยาะเย้ย.\nเฝ้ารอด้วยความอดทนเถิด—— ผู้มีความปรารถนากำลังอยู่บนทางไปสู่งานเลี้ยง."
  },
  StageGroup_146257_Name = {
    Text = "ยามขุนเขาเริงสำราญ"
  },
  StageGroup_146257_TypeText = {
    Text = "การสืบสวน"
  },
  StageGroup_146787_Desc = {
    Text = "คนรุ่นก่อนที่ผ่านไปแล้ว ไม่มีใครจดจำ คนรุ่นหลังที่จะมาถึง คนภายหลังก็ไม่จดจำเช่นกัน.\nการยึดติดกับสิ่งที่สูญสลายไปแล้วนั้นดั่งการจับลม ดังนั้นข้าจึงเกลียดชังชีวิต."
