  },
  StageGroup_15877_Desc = {
    Text = "\"กุญแจทุกดอกมีหมายเลขเฉพาะตัว และจะตรงกับนักสืบสวนเพียงคนเดียวเท่านั้น\"\n\"ดังนั้น การสิ้นสลายของกุญแจแต่ละดอก จึงหมายถึงความตายของนักสืบสวนผู้นั้นเช่นกัน\"\n\"ช่างดีจริงหนอ แม้กระทั่งความตายก็ยังเป็นเอกเทศไม่เหมือนใคร\""
