  StageGroup_15932_Desc = {
    Text = "ทะเลทางตอนเหนือของราชอาณาจักรเลโอ มีช่วงกลางฤดูร้อนที่อ่อนโยนและสงบ \n ฤดูหนาวของเธอดูอ่อนโยนและสง่างาม แต่ภายใต้เมฆสีสวยที่ดูสงบและงดงาม มักจะแฝงไปด้วยพายุที่อันตรายถึงชีวิต"
