  },
  StageGroup_15933_Desc = {
    Text = "ทุกระดับของผู้ปลุกเสก,      ระดับทักษะ,      และความแข็งแรงของของโบราณจะถูกปรับไปที่ระดับ 1.\nสามารถเลือกการสั่นสะเทือนของด่านได้อย่างอิสระ ยิ่งการสั่นสะเทือนมีระดับสูงเท่าไหร่,      รางวัลที่ได้รับเมื่อผ่านด่านก็จะมากขึ้นเท่านั้น."
