  StageGroup_15936_TypeText = {
    Text = "เงาตกค้างไร้ระเบียบ"
  },
  StageGroup_15937_Desc = {
    Text = "ณ ที่แห่งนี้คืออนุสรณ์สถานของมหาวิทยาลัยแห่งหนึ่งซึ่งเต็มไปด้วยรอยแผลนับพันและอ่อนล้าอย่างแสนสาหัส\nมันเคยอุทิศความหวังและกำลังใจอันน้อยนิดให้แก่การดำรงอยู่ของมนุษยชาติ\nส่วนผลลัพธ์เป็นอย่างไรนั้น เจ้าก็ได้เห็นด้วยตาตัวเองแล้วในตอนนี้"
