  },
  StageGroup_15958_Desc = {
    Text = "พิพิธภัณฑ์หุ่นขี้ผึ้งโรเจอร์สตั้งอยู่ลึกที่สุดของถนนเซาท์วาร์ค ใกล้กับสาขาของแม่น้ำเทมส์ \n มันไม่สะดุดตา แต่มีผู้ชื่นชอบศิลปะแนวหน้าจำนวนมากมาเยือน"
