  StageGroup_15958_TypeText = {
    Text = "พิพิธภัณฑ์ขี้ผึ้งบ้าคลั่ง"
  },
  StageGroup_15959_Desc = {
    Text = "พวกมันบิดเบี้ยวและหลอมรวมเข้าหากันในความมืด จากนั้นจึงถูกเก็บรักษาไว้อย่างระมัดระวังภายในรูปปั้น\nนี่คือการหวนคืนสู่กันและกันที่ได้ถูกจัดเตรียมไว้อย่างยาวนาน"
