  StageGroup_15959_TypeText = {
    Text = "บึงเลือดเนื้อ"
  },
  StageGroup_15960_Desc = {
    Text = "ตามบันทึกทางการ มีผู้เข้าร่วมการเดินทัพศักดิ์สิทธิ์ครั้งที่@1 ทั้งหมดสามพันกว่าคน \n เป้าหมายแตกต่างกันไป บางคนเพื่อการดำรงชีวิต บางคนเพื่อล้างแค้น \n และบางคนเพื่อการสังหาร"
  },
  StageGroup_15960_Name = {
