  },
  StageGroup_20222_Desc = {
    Text = "เมื่ออายุได้ห้าขวบ สาวใช้คา밀ล์ถูกพาไปอยู่เบื้องหน้าคุณหนูซาน\n ซานงดงามเหมือนรูปปั้น ท่าทางของเธอสุขุมและลึกลับ เธอส่งยิ้มให้คา밀ล์ท่ามกลางแสงแดด\n ตั้งแต่วันนั้นเป็นต้นมา คาamilล์ได้ตั้งความปรารถนาไว้ว่า เราจะอยู่ด้วยกันตลอดไป"
  },
