  StageGroup_20446_Desc = {
    Text = "ตามตำนานเล่าว่า ใต้เมืองลอนดีเนี่ยน มีประตูเพียงบานเดียวเท่านั้น \n ซึ่งมันนำไปสู่ที่อยู่ของพระเจ้าแห่งความซีด.."
