  StageGroup_20446_TypeText = {
    Text = "การล่องเรือในจิตสำนึก"
  },
  StageGroup_20447_Desc = {
    Text = "เธอเป็นตุ๊กตาที่ถูกสร้างขึ้นใหม่โดยมหาวิทยาลัยมิซากะ \n โครงกระดูกของเธอทำจากโลหะ หัวใจของเธอคือแกนเงิน โครงสร้างของเธอซับซ้อนอย่างยิ่ง แม้มีแบบแปลนการออกแบบ ก็แทบเป็นไปไม่ได้ที่จะสร้างอีกตัวหนึ่งได้ \n และก่อนที่เธอจะกลายเป็นเครื่องจักรที่ไร้ความรู้สึก เธอเคยมีหัวใจของมนุษย์"
  },
