    Text = "มหาสมุทรหนึ่งตายไปแล้ว เธอปกปิดร่างของทะเลนั้น\nในเงาสะท้อนของทะเลลึก ความฝันของกษัตริย์จางหาย และอาณาจักรแห่งเทพก็ได้เสื่อมสลาย\nเธอเห็นตัวเองก้าวออกมาจากภาพลวงในอดีต สู่ซากปรักหักพังของอนาคตที่พินาศ\nเธอถามกับเหว เหวนั้นเงียบงัน\nเธอถวายเครื่องสังเวยแด่เหว แต่คำตอบที่ได้กลับมานั้นมีเพียงแค่ตัวเธอเอง"
  },
