  StageGroup_55453_Desc = {
    Text = "ข้อความทั้งหมดกลายเป็นเถ้าถ่าน，กลีบดอกไม้ทั้งหมดร่วงโรยกลายเป็นโคลน \n สูดลมหายใจจากเปลวเพลิงที่เหลือในสวน，ให้ฉันได้แต่งบทกวีอีกบทเพื่อเธอ \n ในหัวใจที่เงียบเหงาของผู้คน，กุหลาบสีแดงเข้มกำลังพำนักอยู่"
