  StageGroup_56440_Desc = {
    Text = "ผู้พิทักษ์เผลอก้าวเข้าสู่กระดานหมากรุกที่「พระองค์」ได้วางไว้\nพระจันทร์แดง, บ้านโบราณ, พายุหิมะ และผู้เข้าร่วมที่แต่ละคนมีจุดมุ่งหมายซ่อนเร้น...\nการประลองของใจและสมอง กำลังจะเริ่มขึ้นแล้ว"
  },
  StageGroup_56440_Name = {
    Text = "การล่าสัตว์ให้สนุก!"
  },
  StageGroup_56440_TypeText = {
