  StageGroup_56441_TypeText = {
    Text = "บันทึกพิเศษ"
  },
  StageGroup_56443_Desc = {
    Text = "หิมะหนาปกคลุมการหายใจอันเงียบสงบของภูเขา และชะตากรรมที่ผู้กลับสู่ถิ่นฐานต่างค้นหา \n ในเอลวอสซึ่งหนาวเย็นตลอดปี นักรบยกดาบในมือขึ้น \n สิ่งที่เธอจะต่อสู้เพื่อนั้น คือฤดูใบไม้ผลิครั้งแรกในชีวิตของเธอ"
