  StageGroup_67785_Desc = {
    Text = "พระองค์ทรงฝันไปอย่างยาวนาน.\nพระองค์ทรงฝันเห็นเทพเจ้าและดวงดาว ทรงฝันเห็นฝุ่นละอองพัฒนาเป็นอารยธรรม และอารยธรรมกลายเป็นฝุ่นละออง.\nพระองค์ทรงฝันเห็นความเกลียดชังและความรัก ทรงฝันเห็นความสุขและความหวาดกลัว.\nพระองค์ทรงตื่นขึ้นจากความฝัน ทุกสิ่งในความฝันไม่เคยมีอยู่จริง."
  },
  StageGroup_67785_Name = {
    Text = "เมื่อความฝันอันยาวนานถึงจุดสิ้นสุด"
  },
  StageGroup_67785_TypeText = {
    Text = "การสืบสวนยาก"
  },
  StageGroup_67786_Desc = {
