  StageGroup_70938_Desc = {
    Text = "สถานรักษาพยาบาลที่ถูกสร้างด้วยจิตใต้สำนึกของกลุ่ม\nที่นี่ การสูญสลายของร่างกายไม่ใช่จุดสิ้นสุด ความตายของจิตใจคือจุดสิ้นสุด.\nผู้ที่ก้าวเข้ามา ขอให้รักษาสติไว้ มนุษยชาติเป็นที่พึ่งเดียวของคุณในการเดินผ่านเขาวงกตจิตใจ."
  },
  StageGroup_70938_Name = {
    Text = "การเปลี่ยนแปลง"
  },
  StageGroup_70938_TypeText = {
    Text = "การสืบสวน"
  },
  StageGroup_70939_Desc = {
    Text = "เมืองร้างในวันวานที่ถูกฝังอยู่ใต้หมอกสีเทา\nข้ามดวงดาวที่ไร้แสง และพบกับเศษเสี้ยวแห่งเจตจำนงสูงสุดในมิติที่ถูกทำลาย"
  },
  StageGroup_70939_Name = {
    Text = "กลับมาที่ลอนดอนเมืองแห่งสายหมอก"
  },
  StageGroup_70939_TypeText = {
    Text = "การสืบสวน"
  },
  StageGroup_70940_Desc = {
    Text = "เฉลิมฉลองเถิด เพื่อนรัก♪\nกระดูกใต้แสงจันทร์เบ่งบานอย่างเงียบงัน เธอผู้เป็นที่รักถูกวางไว้บนจาน♪\nแขกทุกคนมาถึงแล้ว! ร้องเพลง เต้นรำ♪\nเราจะไม่ภาวนาให้ผู้ล่วงลับ เราจะไม่ไว้ทุกข์ให้ศพ♪\nเธอได้มอบความจำไว้กับฉัน เธอได้มอบน้ำตาไว้กับฉัน♪\nให้เรากลืนวิญญาณและซากเน่าของเธอลงไป♪\nในงานเลี้ยงแห่งความตาย เราจะได้พบกันอีกครั้ง♪"
  },
  StageGroup_70940_Name = {
    Text = "ความสามารถในการกินอย่างอิ่มหนำ"
  },
  StageGroup_70940_TypeText = {
    Text = "การสืบสวน"
  },
  StageGroup_71850_Desc = {
    Text = "เกียรติยศ ความเคารพ และอำนาจที่ไร้ขีดจำกัด ตำแหน่งของกษัตริย์เป็นสิ่งสูงสุดเหนือทุกสิ่ง \n สิ่งที่จำเป็นในการขึ้นสู่บัลลังก์คือการได้รับเลือกจากเทพเจ้า \n แล้วราคาที่ต้องจ่ายสำหรับทั้งหมดนี้จะเป็นเช่นใด?"
  },
  StageGroup_71850_Name = {
    Text = "วันราชาภิเษก"
  },
  StageGroup_71850_TypeText = {
    Text = "การล่องเรือในจิตสำนึก"
  },
