  StageGroup_74238_Desc = {
    Text = "คืนที่เปลวไฟลุกโหมจนท้องฟ้าถูกปกคลุม ไม่ได้มีเพียงแค่ศิลปะของเธอที่ได้รับการฟื้นคืนชีพ"
