  StageGroup_74238_Name = {
    Text = "ความหลงใหลจมสู่ผุยผง"
  },
  StageGroup_74238_TypeText = {
    Text = "การล่องเรือในจิตสำนึก"
  },
  StageGroup_74338_Desc = {
    Text = "การเล่นหมากรุกเฟสได้ต้อนรับผู้มีความลี้ลับ สาวน้อยที่มีเขาสองข้างได้เสนอการพนันแก่ทุกคน \nรวบรวมเมล็ดโอ๊ค พิชิตศัตรูที่แข็งแกร่ง ทุกอย่างเพื่อพลิกผันพื้นที่อีกครั้ง \nเมื่อแสงสีเงินผ่าฟ้าสว่างไสว ทำลายดวงอาทิตย์ที่ส่องแสงเหนือสรรพสิ่ง สาวน้อยจึงตระหนักขึ้นมา \nที่แท้สิ่งที่เธอยังคงไม่อาจปล่อยวางได้ ก็คือความยึดมั่นจากอดีต \nโซ่ตรวนได้แตกสลาย ความยึดมั่นได้ถูกกำจัด เมื่อสาวน้อยจบการเดินทาง เธอได้มอบพรอันบริสุทธิ์ที่สุดให้กับเพื่อนของเธอ"
  },
  StageGroup_74338_Name = {
    Text = "เทิร์นพลิกเกม"
  },
  StageGroup_74338_TypeText = {
    Text = "การเชื่อมโยงหลายมิติ"
  },
  StageGroup_75263_Desc = {
    Text = "ณ ที่แห่งนี้คืออนุสรณ์สถานของมหาวิทยาลัยแห่งหนึ่งซึ่งเต็มไปด้วยรอยแผลนับพันและอ่อนล้าอย่างแสนสาหัส\nมันเคยอุทิศความหวังและกำลังใจอันน้อยนิดให้แก่การดำรงอยู่ของมนุษยชาติ\nส่วนผลลัพธ์เป็นอย่างไรนั้น เจ้าก็ได้เห็นด้วยตาตัวเองแล้วในตอนนี้"
  },
  StageGroup_75263_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75263_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75264_Desc = {
    Text = "รูปเคารพที่พังทลายกำลังเฝ้ามองเหล่าไพร่พลของตน\nมองพวกเขาดำรงชีวิต แพร่พันธุ์ ห้ำหั่นกันเอง...ก่อนจะหลงลืมตนโดยสมบูรณ์\nรูปเคารพที่พังทลายกำลังโหยหาเหล่าไพร่พลของตน"
  },
  StageGroup_75264_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75264_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75265_Desc = {
    Text = "\"มันคือหนึ่งเดียว มันคือทั้งหมด มันคือความหวังที่จะเปิดประตูแห่งแก่นแท้\"\nกุญแจนับไม่ถ้วนรวมกันเป็นวงกลม พวกมันร่วงหล่นลงมาจากฟากฟ้า นำพาความหวังอันหนักอึ้งมาสู่มวลมนุษย์\nและนำพามาซึ่งหลุมศพอันหนักอึ้งเช่นกัน"
  },
  StageGroup_75265_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75265_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75266_Desc = {
    Text = "\"มือ\" ได้เปิดม่านราตรีกาลออกและย่างกรายเข้าสู่โลกใบนี้อย่างเงียบงัน"
  },
