  StageGroup_75272_Desc = {
    Text = "\"กุญแจทุกดอกมีหมายเลขเฉพาะตัว และจะตรงกับนักสืบสวนเพียงคนเดียวเท่านั้น\"\n\"ดังนั้น การสิ้นสลายของกุญแจแต่ละดอก จึงหมายถึงความตายของนักสืบสวนผู้นั้นเช่นกัน\"\n\"ช่างดีจริงหนอ แม้กระทั่งความตายก็ยังเป็นเอกเทศไม่เหมือนใคร\""
  },
  StageGroup_75272_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75272_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75273_Desc = {
    Text = "รูปเคารพที่พังทลายกำลังเฝ้ามองเหล่าไพร่พลของตน\nมองพวกเขาดำรงชีวิต แพร่พันธุ์ ห้ำหั่นกันเอง...ก่อนจะหลงลืมตนโดยสมบูรณ์\nรูปเคารพที่พังทลายกำลังโหยหาเหล่าไพร่พลของตน"
  },
  StageGroup_75273_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75273_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75274_Desc = {
    Text = "\"กุญแจทุกดอกมีหมายเลขเฉพาะตัว และจะตรงกับนักสืบสวนเพียงคนเดียวเท่านั้น\"\n\"ดังนั้น การสิ้นสลายของกุญแจแต่ละดอก จึงหมายถึงความตายของนักสืบสวนผู้นั้นเช่นกัน\"\n\"ช่างดีจริงหนอ แม้กระทั่งความตายก็ยังเป็นเอกเทศไม่เหมือนใคร\""
  },
  StageGroup_75274_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75274_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75275_Desc = {
    Text = "\"มือ\" ได้เปิดม่านราตรีกาลออกและย่างกรายเข้าสู่โลกใบนี้อย่างเงียบงัน"
  },
  StageGroup_75275_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75275_TypeText = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
  },
  StageGroup_75276_Desc = {
    Text = "ณ ที่แห่งนี้คืออนุสรณ์สถานของมหาวิทยาลัยแห่งหนึ่งซึ่งเต็มไปด้วยรอยแผลนับพันและอ่อนล้าอย่างแสนสาหัส\nมันเคยอุทิศความหวังและกำลังใจอันน้อยนิดให้แก่การดำรงอยู่ของมนุษยชาติ\nส่วนผลลัพธ์เป็นอย่างไรนั้น เจ้าก็ได้เห็นด้วยตาตัวเองแล้วในตอนนี้"
  },
  StageGroup_75276_Name = {
    Text = "ดำดิ่งสู่ห้วงฝันลวงตา"
