  StageGroup_81262_Desc = {
    Text = "นี่ควรจะเป็นการเดินทางที่เต็มไปด้วยเสียงหัวเราะและรอยยิ้ม\nเรือหรูหราล่องลอยในมหาสมุทรแอตแลนติก นำโดยสินค้าชนะเลิศ และโดยความทะเยอทะยานของมนุษย์ที่จะพิชิตมหาสมุทร\nแต่มหาสมุทรมันมีอารมณ์ของมันเอง\nต่อหน้าความน่ากลัวและความไม่รู้ที่เกินไป มนุษย์ ในท้ายที่สุดมันเล็กน้อยเหมือนมด"
