  },
  StageGroup_88933_Name = {
    Text = "ไร้ขอบเขตแห่งทราย"
  },
  StageGroup_88933_TypeText = {
    Text = "กระโดดข้ามท้องฟ้าสีเขียว"
  },
  StageGroup_88934_Desc = {
    Text = "นี่คือเพลงที่นกขับร้องให้ฟ้าผ่า.\nโลกภายนอกเป็นเช่นไร?\nมีอัศวินที่ซื่อสัตย์และเจ้าหญิงที่สวยงาม มีทุ่งหญ้าอันไม่มีที่สิ้นสุดและม้าผ่าเหล่าภูเขา?\nไปเถอะ ไปดูเถอะ เตรียมตัวออกเดินทางวันนี้\nกัดโซ่ตรวนและราวเหล็ก ทำให้บินไปสู่ท้องฟ้าและดวงจันทร์\nไม่ต้องกลัวการบาดเจ็บหรือความหิว\nที่ปลายถนนแห่งเสรีภาพ จะต้องเต็มไปด้วยน้ำพุและดอกไม้"
  },
  StageGroup_88934_Name = {
    Text = "นอกขอบฟ้า·บน"
